// NewListReferenceDataResponseBody builds the HTTP response body from the
// result of the "listReferenceData" endpoint of the "onboarding" service.
func NewListReferenceDataResponseBody(res *onboarding.OnboardingReferenceData) *ListReferenceDataResponseBody {
	body := &ListReferenceDataResponseBody{}
	if res.Products != nil {
		body.Products = make([]*OnboardingProductResponseBody, len(res.Products))
		for i, val := range res.Products {
			if val == nil {
				body.Products[i] = nil
				continue
			}
			body.Products[i] = marshalOnboardingOnboardingProductToOnboardingProductResponseBody(val)
		}
	} else {
		body.Products = []*OnboardingProductResponseBody{}
	}
	if res.UseCases != nil {
		body.UseCases = make([]*OnboardingOptionResponseBody, len(res.UseCases))
		for i, val := range res.UseCases {
			if val == nil {
				body.UseCases[i] = nil
				continue
			}
			body.UseCases[i] = marshalOnboardingOnboardingOptionToOnboardingOptionResponseBody(val)
		}
	} else {
		body.UseCases = []*OnboardingOptionResponseBody{}
	}
	if res.MdmVendors != nil {
		body.MdmVendors = make([]*OnboardingOptionResponseBody, len(res.MdmVendors))
		for i, val := range res.MdmVendors {
			if val == nil {
				body.MdmVendors[i] = nil
				continue
			}
			body.MdmVendors[i] = marshalOnboardingOnboardingOptionToOnboardingOptionResponseBody(val)
		}
	} else {
		body.MdmVendors = []*OnboardingOptionResponseBody{}
	}
	return body
}

