func NewGetOnboardingResponseBody(res *onboarding.OnboardingState) *GetOnboardingResponseBody {
	body := &GetOnboardingResponseBody{
		Done: res.Done,
	}
	if res.Answers != nil {
		body.Answers = marshalOnboardingOnboardingAnswersToOnboardingAnswersResponseBody(res.Answers)
	}
	if res.NextStep != nil {
		body.NextStep = marshalOnboardingOnboardingStepToOnboardingStepResponseBody(res.NextStep)
	}
	if res.Steps != nil {
		body.Steps = make([]*OnboardingStepResponseBody, len(res.Steps))
		for i, val := range res.Steps {
			if val == nil {
				body.Steps[i] = nil
				continue
			}
			body.Steps[i] = marshalOnboardingOnboardingStepToOnboardingStepResponseBody(val)
		}
	} else {
		body.Steps = []*OnboardingStepResponseBody{}
	}
	return body
}

