// ValidateSaveAnswersRequestBody runs the validations defined on
// SaveAnswersRequestBody
func ValidateSaveAnswersRequestBody(body *SaveAnswersRequestBody) (err error) {
	if body.Products == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("products", "body"))
	}
	if body.MdmVendor == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("mdm_vendor", "body"))
	}
	if body.UseCase == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("use_case", "body"))
	}
	for _, e := range body.Products {
		if e != nil {
			if err2 := ValidateOnboardingSelectedProductRequestBody(e); err2 != nil {
				err = goa.MergeErrors(err, err2)
			}
		}
	}
	if body.MdmVendor != nil {
		if !(*body.MdmVendor == "jamf" || *body.MdmVendor == "intune" || *body.MdmVendor == "iru" || *body.MdmVendor == "none") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.mdm_vendor", *body.MdmVendor, []any{"jamf", "intune", "iru", "none"}))
		}
	}
	if body.UseCase != nil {
		if !(*body.UseCase == "observability" || *body.UseCase == "cost-tracking" || *body.UseCase == "security" || *body.UseCase == "mcp-gateway") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.use_case", *body.UseCase, []any{"observability", "cost-tracking", "security", "mcp-gateway"}))
		}
	}
	return
}

